int dccp_getsockopt(struct sock *sk, int optname, int len, u32 __user *optval, int __user *optlen)
{
    int err = 0;
    void *reply = NULL;
    int reply_len = 0;

    if (optname == DCCP_SOCKOPT_CCID_TX_INFO) {
        struct tfrc_tx_info info;

        memset(&info, 0, sizeof(info));
        info.sender_rtt = sk->sk_rto;
        info.packets_acked = sk->sk_ack_backlog;
        info.transmit_rate = sk->sk_pacing_rate;
        reply_len = sizeof(info);
        reply = &info;
    } else {
        return -EINVAL;
    }

    if (len < reply_len)
        return -EINVAL;

    if (put_user(reply_len, optlen))
        return -EFAULT;

    if (copy_to_user(optval, reply, reply_len))
        return -EFAULT;

    return 0;
}

int get_dccp_sockopt(struct sock *sk, int optname, int len, u32 __user *optval, int __user *optlen) {
    if (optname == DCCP_SOCKOPT_CCID_TX_INFO) {
        struct tfrc_tx_info tx_info;
        int err;

        // Initialize tx_info with socket's transmission data
        tx_info.pktSndCnt = sk->sk_dccps_cnt;
        tx_info.pktSndUrgCnt = sk->sk_dccps_urgcnt;
        tx_info.pktSndDataCnt = sk->sk_dccps_datacnt;
        tx_info.pktSndTotal = sk->sk_dccps_totcnt;

        if (len < sizeof(tx_info)) {
            return -EINVAL;
        }

        if (put_user(sizeof(tx_info), optlen))
            return -EFAULT;

        if (copy_to_user(optval, &tx_info, sizeof(tx_info)))
            return -EFAULT;

        return 0;
    }

    return -EINVAL;
}

int dccp_getsockopt(struct sock *sk, int optname, int len, u32 __user *optval, int __user *optlen)
{
    int ret = 0;
    void *user_data;
    int user_len;

    if (optname == DCCP_SOCKOPT_CCID_TX_INFO) {
        struct tfrc_tx_info tx_info;
        int copy_len = min(len, sizeof(tx_info));

        /* Populate tx_info with relevant transmission data from sk */
        tx_info.packets_sent = sk->sk_packets_sent;
        tx_info.bytes_sent = sk->sk_bytes_sent;
        tx_info.last_rtt_us = sk->sk_last_rtt_us;
        tx_info.start_time = sk->sk_start_time;

        if (copy_to_user(optval, &tx_info, copy_len)) {
            ret = -EFAULT;
        }

        if (put_user(copy_len, optlen)) {
            ret = -EFAULT;
        }
    } else {
        ret = -EINVAL;
    }

    return ret;
}

int get_dccp_sock_opt(struct sock *sk, int optname, int len, u32 __user *optval, int __user *optlen)
{
    struct tfrc_tx_info tx_info;

    if (optname != DCCP_SOCKOPT_CCID_TX_INFO)
        return -EINVAL;

    if (len < sizeof(tx_info))
        return -EINVAL;

    /* Populate the tx_info with data from the socket's state */
    tx_info.packets_sent = sk->sk_wmem_queued;
    tx_info.packets_lost = 0;  /* Assume no loss in this example */
    tx_info.packets_acked = sk->sk_ack_backlog;
    tx_info.rate = 0;           /* Placeholder for actual rate calculation */

    if (copy_to_user(optval, &tx_info, sizeof(tx_info)))
        return -EFAULT;

    if (put_user(sizeof(tx_info), optlen))
        return -EFAULT;

    return 0;
}
